package br.tcc.checkout.api;

import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.content;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.http.MediaType;
import org.springframework.test.web.servlet.MockMvc;

@SpringBootTest
@AutoConfigureMockMvc
class CheckoutControllerTest {

	@Autowired
	private MockMvc mockMvc;

	@Test
	void devolveOResumoCombinadoComOSite() throws Exception {
		mockMvc.perform(postResumo("""
				{
				  "itens": [
				    { "nome": "Camiseta", "precoUnitario": 79.90, "quantidade": 2, "pesoKg": 0.30 },
				    { "nome": "Tênis", "precoUnitario": 249.90, "quantidade": 1, "pesoKg": 1.20 }
				  ],
				  "modalidadeEntrega": "EXPRESSA",
				  "cupom": "BEMVINDO10",
				  "formaPagamento": "PIX",
				  "parcelas": 1
				}
				"""))
				.andExpect(status().isOk())
				.andExpect(content().contentTypeCompatibleWith(MediaType.APPLICATION_JSON))
				.andExpect(jsonPath("$.subtotalProdutos").value(409.70))
				.andExpect(jsonPath("$.descontoCupom").value(40.97))
				.andExpect(jsonPath("$.frete").value(33.10))
				.andExpect(jsonPath("$.prazoEntregaDias").value(2))
				.andExpect(jsonPath("$.ajustePagamento").value(-20.09))
				.andExpect(jsonPath("$.totalFinal").value(381.74))
				.andExpect(jsonPath("$.parcelas").value(1))
				.andExpect(jsonPath("$.valorParcela").value(381.74));
	}

	@Test
	void escreveOsValoresComDuasCasasDecimais() throws Exception {
		mockMvc.perform(postResumo("""
				{
				  "itens": [{ "nome": "Meia", "precoUnitario": 20, "quantidade": 1, "pesoKg": 0.1 }],
				  "modalidadeEntrega": "RETIRADA_LOJA",
				  "formaPagamento": "CARTAO",
				  "parcelas": 2
				}
				"""))
				.andExpect(status().isOk())
				.andExpect(content().json("""
						{
						  "subtotalProdutos": 20.00,
						  "descontoCupom": 0.00,
						  "frete": 0.00,
						  "prazoEntregaDias": 1,
						  "ajustePagamento": 0.00,
						  "totalFinal": 20.00,
						  "parcelas": 2,
						  "valorParcela": 10.00
						}
						""", true))
				.andExpect(content().string(org.hamcrest.Matchers.containsString("\"subtotalProdutos\":20.00")));
	}

	@Test
	void cupomEParcelasSaoOpcionais() throws Exception {
		mockMvc.perform(postResumo("""
				{
				  "itens": [{ "nome": "Meia", "precoUnitario": 19.90, "quantidade": 1, "pesoKg": 0.10 }],
				  "modalidadeEntrega": "RETIRADA_LOJA",
				  "cupom": null,
				  "formaPagamento": "PIX"
				}
				"""))
				.andExpect(status().isOk())
				.andExpect(jsonPath("$.descontoCupom").value(0.00))
				.andExpect(jsonPath("$.parcelas").value(1));
	}

	@Test
	void devolve400ComOCodigoDoErroDeNegocio() throws Exception {
		mockMvc.perform(postResumo("""
				{
				  "itens": [{ "nome": "Halter", "precoUnitario": 100.00, "quantidade": 10, "pesoKg": 1.00 }],
				  "modalidadeEntrega": "MOTOBOY",
				  "formaPagamento": "PIX"
				}
				"""))
				.andExpect(status().isBadRequest())
				.andExpect(content().json("{\"erro\":\"MODALIDADE_INDISPONIVEL\"}", true));
	}

	@Test
	void devolve400QuandoOCorpoNaoPodeSerLido() throws Exception {
		mockMvc.perform(postResumo("{ nao é json }"))
				.andExpect(status().isBadRequest())
				.andExpect(jsonPath("$.erro").value("PEDIDO_INVALIDO"));
	}

	@Test
	void devolve400QuandoNaoVemCorpo() throws Exception {
		mockMvc.perform(post("/checkout/resumo").contentType(MediaType.APPLICATION_JSON))
				.andExpect(status().isBadRequest())
				.andExpect(jsonPath("$.erro").value("PEDIDO_INVALIDO"));
	}

	private static org.springframework.test.web.servlet.request.MockHttpServletRequestBuilder postResumo(String corpo) {
		return post("/checkout/resumo").contentType(MediaType.APPLICATION_JSON).content(corpo);
	}
}
