				  "parcelas": 1
				}
				""");

		assertThat(resultado).hasStatusOk().hasContentTypeCompatibleWith(MediaType.APPLICATION_JSON)
				.bodyJson().isStrictlyEqualTo("""
						{
						  "subtotalProdutos": 409.70,
						  "descontoCupom": 40.97,
						  "frete": 33.10,
						  "prazoEntregaDias": 2,
						  "ajustePagamento": -20.09,
						  "totalFinal": 381.74,
						  "parcelas": 1,
						  "valorParcela": 381.74
						}
						""");
