				{
				  "itens": [{ "nome": "Meia", "precoUnitario": 20, "quantidade": 1, "pesoKg": 0.1 }],
				  "modalidadeEntrega": "RETIRADA_LOJA",
				  "formaPagamento": "CARTAO",
